import type { ChapterSaga, DialogueLine, Shot } from '../types';

// Chapter II — The Velvet Curtain. The Royal Gloaming Theatre, Gloria Ambre’s unending note,
// Madame Gloam, and Count Valerian Rosenthal’s forty years of roses.
// Side characters (plain display names): Abel Finch (the Prompter), Clara Moss (the understudy),
// Maestro Benedetti (the conductor), Nettie Clare (the programme girl), Gloria Ambre herself.
// Refrains: the brass motto EVERY NIGHT A NEW NIGHT; “after the curtain”; two taps on the boards,
// “like a friend at the door”; “flat”; Columbine’s one-two-three; and the note, which goes on —
// until, in ch2_end, it does not. The aria “Remember My Name” holds its last note on the word name.

const OPEN: Shot[] = [
  { kind: 'title', kicker: 'CHAPTER II', title: 'The Velvet Curtain', sub: 'The Royal Gloaming Theatre' },
  { kind: 'narrate', bg: 'street', tone: 'cold', text: 'The night after Corvid Lane came back to itself, it rained — if rain is the word for water falling from a sky that has not moved in a year. It came straight down, without wind, and hissed on the troupe’s lamps like something being told to hush.' },
  { kind: 'narrate', text: 'Proscenium Hill. Tram rails climbing it and stopping, as though they had lost their nerve. A hoarding for liver salts. A cab without a horse. And at the top, where the trams once turned for the last show, the Royal Gloaming Theatre, its doors open the way a mouth is open in sleep.' },
  { kind: 'narrate', text: 'White stone gone the grey of a pigeon’s breast. Plaster muses along the cornice, their faces smudged to thumbprints by soot long before the Dimming came to finish the job. And over the portico, in brass letters a foot high, the promise the house had made for fifty-eight years:' },
  { kind: 'narrate', text: 'EVERY NIGHT A NEW NIGHT.' },
  { kind: 'narrate', text: 'The gala poster by the doors had been pasted up on the morning of the thirty-first, and the rain had not touched it. NEW YEAR’S GALA. A FAREWELL. Beneath, in the typeface kept for royalty and the dead, a name the Dimming had rubbed to a pale smear, like breath on a cold pane.' },
  { kind: 'line', who: 'wren', text: 'The crows would not come past the tram stop. Eleven years of rounds, and I have never known them refuse an address. Crust sat on the wire and looked at me as if I had insulted his mother.' },
  { kind: 'line', who: 'odile', text: 'Birds know a house that eats light. They are wiser than we are. They have less to unlearn.' },
  { kind: 'line', who: 'bastian', text: 'Listen. Under the rain. Do you hear it?' },
  { kind: 'narrate', text: 'They heard it. One note, held so high and so long that it had stopped sounding like music and begun to sound like the building itself — the ring a wineglass gives under a wet fingertip, if the glass were the size of a cathedral and the finger had never lifted.' },
  { kind: 'line', who: 'bastian', text: 'And under the note — the waltz. One, two, three. One, two, three. It has lived in my joints since Whitlock’s window. I thought I had made it up, to keep myself company.' },
  { kind: 'narrate', text: 'Corvin turned a ticket over in his gloved fingers — the one the Hollow Usher had carried on Corvid Lane. STALLS · ROW K · SEAT 14. ADMIT ONE. THE GALA OF THE THIRTY-FIRST. A week’s wages, by the price printed on it. The stub had never been torn.' },
  { kind: 'line', who: 'wren', text: 'Then we are expected. After a fashion. It would be rude not to go in.' },
  { kind: 'bg', bg: 'theatre', tone: 'warm' },
  { kind: 'narrate', text: 'Inside, the foyer was a sentence the last guest had left unfinished. Fur coats asleep on their hooks. Brass cloakroom tags at their collars, like medals for some small forgotten war. A cigarette laid in a tray, its long grey ash unbroken: the whole shape of a thing, with nothing in it.' },
  { kind: 'narrate', text: 'Along the marble bar stood two hundred glasses of champagne, poured at a quarter to midnight and gone as flat as pond water. Beside one lay a woman’s glove, its fingers still curled, very politely, around nothing.' },
  { kind: 'narrate', text: 'Overhead hung the great chandelier — four thousand drops of Murano crystal, every one of them dark — turning slowly on its chain in a room without a draught, the way a sleeper turns toward a voice it almost knows.' },
  { kind: 'line', who: 'odile', text: 'Someone has been keeping the dust off the banisters.' },
  { kind: 'line', who: 'wren', text: 'Someone has been keeping a great many things.' },
  { kind: 'narrate', text: 'At the foot of the grand staircase a single gas bracket burned. Beneath it, on the bottom step, a man in a crimson coat was arranging roses in a champagne bucket with the patience of a surgeon and the eye of a jeweller.' },
  { kind: 'narrate', text: 'He was not young. His hair had gone the colour of old brass; his face had the fine ruin of a man who had laughed through a great many first nights and wept through a few last ones. The roses in his hands were so red they seemed the only colour left in Vellmoor.' },
  { kind: 'line', who: 'marigold', text: 'You are late. The overture was a year ago.' },
  { kind: 'line', who: 'wren', text: 'Corvin Vesper. I carry the night post on Corvid Lane.' },
  { kind: 'line', who: 'marigold', text: 'I know who you are, Lantern Keeper. One does not sit in the dark for a year without noticing the only light that moves. Valerian Rosenthal. Count — for what that is worth tonight, which is rather less than a good umbrella.' },
  { kind: 'line', who: 'marigold', text: 'Forgive me if I do not rise. I have kept this lamp alight since New Year’s Eve, and it has grown jealous, as kept things do. Look away from it for a moment and it sulks down to a blue bead.' },
  { kind: 'line', who: 'odile', text: 'A year. Alone, with one flame.' },
  { kind: 'line', who: 'marigold', text: 'Not alone. I had the roses. They are excellent company. They bloom on credit, they never wilt, and not once in a year have they asked me what I am waiting for.' },
  { kind: 'line', who: 'bastian', text: 'What are you waiting for?' },
  { kind: 'narrate', text: 'The Count looked at the marionette a long moment — the red silk, the porcelain wrists, the cut strings trailing from her shoulders like the ends of a ribbon after the present has been opened and the child carried up to bed.' },
  { kind: 'line', who: 'marigold', text: 'An encore, my dear. What else does anyone wait for in a theatre?' },
  { kind: 'line', who: 'marigold', text: 'Come. You should see the house. Everyone ought to see it once. It was the most beautiful room in the world, and I say so as a man who has been politely asked to leave most of the others.' },
  { kind: 'narrate', text: 'The auditorium opened before them like a rose cut through the middle: five tiers of gilded boxes curving round the dark like petals, the stalls falling away in velvet rows to the pit, and beyond, framed in gold, the stage, and a curtain the colour of wine held up to a candle.' },
  { kind: 'narrate', text: 'The curtain was up. The stage was bare. A single spotlight lay on the boards in a pale circle, as though it had been told to wait there for someone, and nobody had ever come back to tell it to stop.' },
  { kind: 'narrate', text: 'And every seat was full.' },
  { kind: 'narrate', text: 'Two thousand people in their evening clothes, programmes open on their knees. Pearls at throats. Opera glasses in gloved hands. A small girl asleep against her father’s shoulder. An old man with a brass hearing trumpet, still turned faithfully toward the stage.' },
  { kind: 'line', who: 'odile', text: 'They are breathing. The woman in the third row — her fan is moving.' },
  { kind: 'line', who: 'marigold', text: 'They breathe. They blink. Now and then one of them applauds, very softly, at nothing in particular. They have only forgotten why they came. And that they are allowed to leave.' },
  { kind: 'narrate', text: 'Corvin lifted a programme from an empty aisle seat. THE GLASS SWAN — AN OPERA IN THREE ACTS. Inside, the cast list had faded to ruled lines. Every name gone: the composer’s, the conductor’s, even the printer’s at the foot of the last page, where nobody ever looks.' },
  { kind: 'line', who: 'wren', text: 'The Dimming takes the names first. It always begins with the names. A thief who steals the addresses, and leaves the letters to wander.' },
  { kind: 'line', who: 'marigold', text: 'It did not take hers. Not from me.' },
  { kind: 'narrate', text: 'He sat — not in a seat, but on the top step of the stalls aisle, the bucket of roses between his polished shoes — and told it the way men tell a battle: carefully, out of order, circling back to one moment as if, approached from a new side, it might surrender.' },
  { kind: 'line', who: 'marigold', text: 'The Gloaming was the jewel of Vellmoor. On the last night of 1929 it sold every seat for the New Year’s Gala. Standing room went at auction. A duchess wept in the box office and was not, for once, pretending.' },
  { kind: 'line', who: 'marigold', text: 'It was a farewell. Gloria Ambre — our prima donna, our… I was going to say our treasure, but she would have laughed at me. Our Gloria. Thirty-eight years on that stage. She meant to sing the Swan one last time, and then, she said, to learn how to sit in the audience.' },
  { kind: 'line', who: 'wren', text: 'You remember her name. The Dimming should have taken it with everything else.' },
  { kind: 'line', who: 'marigold', text: 'I paid for every lamp in this house, Keeper. I do not forget my investments. Nor my friends.' },
  { kind: 'line', who: 'odile', text: 'Then your memory still glows. You are a Luminary, Count.' },
  { kind: 'line', who: 'marigold', text: 'Is that what it is called? I had assumed it was simply stubbornness with good tailoring.' },
  { kind: 'line', who: 'marigold', text: 'The Glass Swan is a foolish, perfect opera. A swan becomes a woman for one winter, and a lamplighter falls in love with her. At midnight on the last night of the year she must turn to glass — unless someone who loves her says her true name aloud.' },
  { kind: 'line', who: 'marigold', text: 'The last aria is hers. “Remember My Name.” She sings it on the lamplighter’s bridge with the snow coming down — paper snow; I paid for that too — and at the end she holds one note, the highest in the part, while the bells ring in the new year.' },
  { kind: 'line', who: 'bastian', text: 'How does it go?' },
  { kind: 'line', who: 'marigold', text: 'You would not want me to sing it. Nobody has ever wanted me to sing anything. But I can say it. I have said it every night for a year, the way a man says his prayers to a God to whom he has not been introduced.' },
  { kind: 'letter', text: 'The river’s turned to glass, my love,\nthe bridge is white with snow;\nthe bells have come to count the year,\nand I have far to go.\n\nBefore your lamp I was a bird;\nby morning I’ll be glass —\na thing the light goes clean through, love,\nand never stops to ask.', sign: '— The Glass Swan, Act III' },
  { kind: 'letter', text: 'So when the last bell leaves the air\nand all the lamps go blind,\ndon’t bring me roses — bring me this,\nthe one thing left behind.\n\nRemember my name.', sign: '— “Remember My Name”' },
  { kind: 'line', who: 'marigold', text: 'The note is on the last word. She opens the word name like a door — just the vowel of it, held — and stands in the doorway until the tenor answers. She has been holding the word name for a year. Long enough, I should think, to forget it was ever a word.' },
  { kind: 'line', who: 'marigold', text: 'And over that note the tenor answers. One word: her name. That is the whole trick of it. The note waits, the name comes, the swan is saved, and two thousand people go home weeping happily into their furs.' },
  { kind: 'line', who: 'bastian', text: 'And that night?' },
  { kind: 'line', who: 'marigold', text: 'That night they timed the last scene to the Cathedral Clock itself. The great doors were opened to the street so the real bells would ring over the music. Gloria’s idea. She wanted the whole city in her final scene. She got it.' },
  { kind: 'bell', strokes: 12, text: 'Twelve strokes rolled down Proscenium Hill and in through the open doors, like guests arriving late.' },
  { kind: 'line', who: 'marigold', text: 'I counted them. I always count — a habit from my father, who counted everything, his children included, and generally came up one short. Twelve. Gloria held the note. The tenor drew breath for her name.' },
  { kind: 'bell', strokes: 1, ominous: true, text: '…and then a thirteenth.' },
  { kind: 'line', who: 'marigold', text: 'Gloria sang at midnight. I was in my box. The thirteenth stroke landed in the middle of her final note… and the note never ended.' },
  { kind: 'line', who: 'marigold', text: 'It sounded nearer than the others. I have told myself since that it was the acoustics. This house plays tricks with sound. It was built to.' },
  { kind: 'line', who: 'marigold', text: 'Every lamp went out. The tenor opened his mouth and nothing came, because he no longer knew whose name he was meant to sing. Nobody did. Two thousand people forgot her in the space of one breath. Two thousand, less one.' },
  { kind: 'line', who: 'marigold', text: 'She is still singing. You can hear her now, if you stop listening to me — which, I am reliably informed, most people find quite easy.' },
  { kind: 'narrate', text: 'They listened. The note filled the house the way water fills a jar: from the bottom up, into every corner, until no part of the air was not it. It did not waver. It did not breathe. It had not breathed since the last night of the year.' },
  { kind: 'line', who: 'odile', text: 'A held note is a question. It is waiting for its answer.' },
  { kind: 'line', who: 'marigold', text: 'Yes. And I have sat here a year working out how to give it one. I cannot sing, you understand. I have the voice of a gate that wants oiling. Gloria said I was the only man alive who could make the national anthem sound like an apology.' },
  { kind: 'narrate', text: 'From his breast pocket he drew a small card, its cream gone soft at the corners from handling, the way a coin goes smooth in a pocket. Pinned to it was a single pressed rose petal, brown as tea.' },
  { kind: 'line', who: 'marigold', text: 'She sent this up to my box at the second interval. I did not read it until afterwards. There was no afterwards. So I have read it every night since, instead.' },
  { kind: 'letter', text: 'Valerian — Don’t you dare leave before the curtain. Come to my dressing room after, and bring nothing; you have sent me roses enough to bury a regiment. There is something I have been rehearsing for half my life, and I should like, for once, to say it without a prompter.', sign: '— G.' },
  { kind: 'line', who: 'wren', text: 'What was it?' },
  { kind: 'line', who: 'marigold', text: 'I have no idea. That is rather the tragedy, Keeper. One always assumes there will be time to find out. Time was the one thing in this city I never thought to buy.' },
  { kind: 'narrate', text: 'Nobody spoke. Somewhere in the dark of the upper tiers, one pair of gloved hands clapped twice, softly, and stopped.' },
  { kind: 'line', who: 'bastian', text: 'Count. You said she is still singing. Where?' },
  { kind: 'line', who: 'marigold', text: 'She is on the stage. She has been singing for a year.' },
  { kind: 'line', who: 'wren', text: 'The stage is empty.' },
  { kind: 'line', who: 'marigold', text: 'Look again.' },
  { kind: 'narrate', text: 'They looked. In the spotlight’s pale circle something moved — not a woman, exactly, but the shape a woman leaves in smoke after she has walked through it. Violet, and tall, and trailing a hem that glittered like a city seen from a hill at night.' },
  { kind: 'narrate', text: 'The lights in that hem were not sequins. They were fireflies — hundreds of them, stitched into the velvet by their wings, each one pulsing faintly with a name that was not hers.' },
  { kind: 'line', who: 'odile', text: 'The woman on the balcony. Madame Gloam.' },
  { kind: 'line', who: 'bastian', text: 'She is wearing them. Corvin — she is wearing people.' },
  { kind: 'line', who: 'gloam', text: 'Visitors. How lovely. Nobody visits any more, darlings. They come, and they stay, and that is not at all the same thing.' },
  { kind: 'narrate', text: 'The voice came from everywhere at once — the boxes, the pit, the seams between the floorboards. And beneath it the note went on, unbroken. She was speaking and singing together, as though with two throats: one for the song, and one for the dark.' },
  { kind: 'line', who: 'gloam', text: 'Two voices, darling. One for singing, and one for everything else. The Dimming is generous to its favourites.' },
  { kind: 'line', who: 'gloam', text: 'Each light a name your city would not keep. I keep them, darling. Somebody must keep.' },
  { kind: 'line', who: 'marigold', text: 'Gloria.' },
  { kind: 'narrate', text: 'The figure did not turn. The note did not falter. If the name reached her at all, it fell on her the way snow falls on a window — and slid away.' },
  { kind: 'line', who: 'gloam', text: 'Gloria? Some girl in the chorus, I expect. I never learn the chorus’s names. Nobody does. That is what a chorus is for.' },
  { kind: 'line', who: 'marigold', text: 'She sang in the chorus two years before anyone learned her name. She called it the finest education an artist could have. It teaches you precisely how much the world is prepared to forget.' },
  { kind: 'line', who: 'gloam', text: 'And one of you carries a lantern. A whole lantern. Do you know how long it has been since I had anything so bright to wear?' },
  { kind: 'line', who: 'wren', text: 'This one is not for wearing. It is for delivering.' },
  { kind: 'line', who: 'gloam', text: 'Everything is for wearing, Postman. Ask the moths. Ushers — show our guests to their seats. Row K, I believe. Seat fourteen.' },
  { kind: 'narrate', text: 'Corvin looked down at the ticket in his hand. He had not said the seat aloud. He had shown it to no one.' },
  { kind: 'narrate', text: 'In the aisles, black-veiled statues turned their heads together with the sound of stone remembering it can move — the Velvet Widows from the theatre garden. Behind them, from every exit, the Hollow Ushers came, lifting their dead lanterns like collection plates.' },
  { kind: 'line', who: 'odile', text: 'Corvin.' },
  { kind: 'line', who: 'wren', text: 'I see them. Columbine, take the aisle. Seraphine, stay behind the Count.' },
  { kind: 'line', who: 'marigold', text: 'Behind me? My dear Keeper, I have sat through the whole of the Ring Cycle four times. Nothing left in this house can frighten me.' },
  { kind: 'narrate', text: 'He drew a rose from the bucket. In his hand its stem lengthened, thorn by thorn, until he held something nearer a rapier than a flower — and it was still, absurdly, a rose.' },
  { kind: 'line', who: 'marigold', text: 'Besides. These are my seats. I paid for the velvet.' },
  { kind: 'line', who: 'bastian', text: 'One, two, three—' },
  { kind: 'line', who: 'wren', text: 'Light the Lantern.' },
  { kind: 'narrate', text: 'And beneath it all, patient as a held breath, the note went on.' },
];

// After 2-2 — the Prompter is found, and with him the beginning of Gloria’s story.
const I1_PROMPTER: Shot[] = [
  { kind: 'narrate', text: 'The prompter’s box sits at the lip of the stage like a shell half buried in sand: a hooded cave of painted wood, turned toward the singers, so that the audience sees nothing of the man inside but now and then a glint of spectacles — a small moon that rises only when someone forgets.' },
  { kind: 'narrate', text: 'When the last Ink Hound had poured itself back into the floorboards, Columbine knelt at the footlights and looked inside. A man looked back at her.' },
  { kind: 'narrate', text: 'He was very small and very old, folded into the box like a letter into its envelope. His fingers were black with ink to the second knuckle. Before him lay a script so thick it had been bound with bootlaces, its pages gone soft as cloth from thumbing.' },
  { kind: 'line', who: 'The Prompter', text: '“—and if the snow should cover every road, my love, I’ll find you by your—” No. No, that is the second act. Who moved the page? Who has been moving my pages?' },
  { kind: 'line', who: 'bastian', text: 'Nobody, sir. We were fighting. I am sorry about the noise.' },
  { kind: 'line', who: 'The Prompter', text: 'Noise is not my department. Lines are my department. Twenty years I have given the lines in this house, and not one singer has dried on my watch. Not one.' },
  { kind: 'line', who: 'wren', text: 'What is your name, sir?' },
  { kind: 'narrate', text: 'The old man opened his mouth, and shut it, and his inky hands went searching across the script as though his name might be in there somewhere — in a margin, in pencil, in the small hand prompters keep for things that are not meant to be read aloud.' },
  { kind: 'line', who: 'The Prompter', text: 'It is… it is in the book. Everything is in the book. If it is not in the book, it was never said.' },
  { kind: 'narrate', text: 'Corvin had seen this on Corvid Lane: the particular stillness of someone who has gone looking for their own name and found a blank page where it ought to be. He opened his satchel and went through the envelopes one by one, the way you go through a drawer for a key.' },
  { kind: 'line', who: 'wren', text: 'Sometimes the crows bring me a letter before I know whose it is. Let me see. Here — Mr. Abel Finch. Care of the Royal Gloaming Theatre. The Prompter’s Box. Front of Stage. Not a large address. But a very precise one.' },
  { kind: 'line', who: 'Abel Finch', text: 'Finch. Abel Finch. Yes. My mother called me Abel when she was cross and Abie when she was not. Give it here, son — my eyes are not what they were, but they are still better than my memory.' },
  { kind: 'narrate', text: 'The envelope was creased and water-stained. It had been written in a hurry, in a dressing room, on the last evening of the year — and it had spent the year since in the dark, looking for someone who still knew who had written it.' },
  { kind: 'letter', text: 'Dear Abie — Thank you. For twenty years you have caught me every time I fell, and not one soul in the house ever saw me falling. If I dry tonight, don’t give me the line straight away. Let me stand in the silence a moment. I want to know what it feels like up there with nothing to say.', sign: '— G.A., the thirty-first' },
  { kind: 'line', who: 'Abel Finch', text: 'Gloria.' },
  { kind: 'line', who: 'Abel Finch', text: 'Gloria. Oh, my girl. She never dried. Not once in twenty years. Not until—' },
  { kind: 'line', who: 'marigold', text: 'Not until midnight.' },
  { kind: 'line', who: 'Abel Finch', text: 'Count Rosenthal. You have got old.' },
  { kind: 'line', who: 'marigold', text: 'And you were always old, Finch. It saved a great deal of time.' },
  { kind: 'line', who: 'Abel Finch', text: 'When she wanted a line, she’d tap her heel on the boards. Twice. Right above my head. Nobody in the stalls ever saw it. Two little knocks, like a friend at the door.' },
  { kind: 'line', who: 'Abel Finch', text: 'At midnight she tapped. Twice. I felt it come down through the wood into my hands. Only it wasn’t her own line she wanted — it was his. The tenor’s. He’d gone white as milk. He had forgotten her name.' },
  { kind: 'line', who: 'Abel Finch', text: 'So I looked down to give it him. And it was gone. Off the page. Off every page. Every “Gloria” I had pencilled in the margins for twenty years — gone, as if someone had drawn in a breath and taken the ink in with it.' },
  { kind: 'line', who: 'Abel Finch', text: 'I did the only thing a prompter can do when the book fails him. I crossed out everything else. Every line in the opera, one at a time, all night, by the light of my little lamp.' },
  { kind: 'line', who: 'Abel Finch', text: 'So the only words left on the page would be the ones that mattered. I thought: if there is nothing else to read, the name will have to come back. Nature hates an empty page.' },
  { kind: 'narrate', text: 'He turned the great book round to show them. Page after page of black ink, struck through and struck through again, until the paper had gone stiff as a board. And on the last page, alone, underlined twice so hard the nib had torn through: Remember my name.' },
  { kind: 'line', who: 'odile', text: 'You have been prompting her for a year.' },
  { kind: 'line', who: 'Abel Finch', text: 'Every night. She hasn’t taken the cue. But a prompter doesn’t stop because the singer isn’t listening, miss. You keep the place. That is the whole of the job. You keep the place, so when they come back, they know where they are.' },
  { kind: 'line', who: 'wren', text: 'That is my job too. More or less. I keep people’s places until they come back for them.' },
  { kind: 'line', who: 'Abel Finch', text: 'Then you’ll know it is a lonely one. And that it is worth it.' },
  { kind: 'bg', bg: 'theatre', tone: 'warm' },
  { kind: 'narrate', text: 'While Seraphine bound his hands — they were cold as the boards, and shook — Abel Finch talked. Prompters, it turns out, have a lifetime of things saved up to say, having spent it whispering other people’s.' },
  { kind: 'line', who: 'Abel Finch', text: 'She wasn’t Ambre then. She was Glory Ambler, from the laundries on Tallow Street. Came to the wardrobe room at fourteen to sew spangles on other girls’ hems. Fifty to a hem. She could do a hem in an evening and sing the whole second act while she did it.' },
  { kind: 'line', who: 'Abel Finch', text: 'I was callboy then. Knocking on doors. “Fifteen minutes, miss. Five minutes, miss.” And every night, going past the wardrobe room, I heard a voice under the door singing the soprano part better than the soprano.' },
  { kind: 'line', who: 'marigold', text: 'That is where I first heard her. In a corridor. I was twenty-two and lost — my father had sent me to the Gloaming to learn for myself that the theatre was a frivolous waste of money. I was looking for the way out. Then that voice came through a door.' },
  { kind: 'line', who: 'marigold', text: 'I opened it. A girl with a mouthful of pins looked up at me and said, “If you’re the new tenor, you’re flat.” I was not the new tenor. I have been flat ever since.' },
  { kind: 'line', who: 'bastian', text: 'She sewed lights into hems.' },
  { kind: 'narrate', text: 'Nobody answered her. Up on the stage the empty spotlight trembled, and for a moment they all saw again the violet train, glittering with stolen fireflies. Fifty to a hem.' },
  { kind: 'line', who: 'odile', text: 'And now she wears them.' },
  { kind: 'line', who: 'Abel Finch', text: 'The Dimming knows what we were. That’s the cruel trick of it. It doesn’t make you into something new. It makes you into what you were — with the meaning taken out.' },
  { kind: 'line', who: 'Abel Finch', text: 'Eighteen ninety-one. The company soprano loses her voice on opening night. The manager walks out to say the performance is cancelled — and from the back of the chorus this girl steps forward in a borrowed gown with the pins still in it, and says: “I know it.”' },
  { kind: 'line', who: 'Abel Finch', text: 'And she did. Every note, every word. Learned the whole part through a wardrobe door. They let her go on because they had nothing left to lose. By the interval the manager was crying. By the curtain call he had given her a new name.' },
  { kind: 'line', who: 'Abel Finch', text: '“Ambre,” he said, “because you glow like it.” And she let him have it, because she was sixteen and had never in her life been given anything new.' },
  { kind: 'line', who: 'marigold', text: 'I sent roses the next morning. A dozen, red, with a card: From the flat gentleman in the corridor. She sent one back. “Tell your father it was a frivolous waste of money. — G.”' },
  { kind: 'line', who: 'marigold', text: 'We kept that up for thirty-eight years: a correspondence in flowers. Every opening night I sent roses, and every opening night she sent one back, like change from a large note. I have them all, pressed, in a book I am not permitted to show anyone.' },
  { kind: 'line', who: 'bastian', text: 'Who will not permit it?' },
  { kind: 'line', who: 'marigold', text: 'I will not. I have a reputation to consider. It is mostly fictional, but I am very attached to it.' },
  { kind: 'line', who: 'Abel Finch', text: 'If you mean to reach her, go down by the dressing rooms. The mirrors there remember things — they’ve seen every face in this house with its guard down. Hers is the room with the star on the door.' },
  { kind: 'line', who: 'wren', text: 'Will you come with us, Mr. Finch?' },
  { kind: 'line', who: 'Abel Finch', text: 'No, son. I’ll stay. I’ll keep the place. And if she dries — if she ever stands up there wanting the line — you tap twice on those boards for me. I’ll be listening. I am always listening.' },
  { kind: 'narrate', text: 'As they went they heard him turning pages behind them, and then, beneath the endless note, an old man whispering a single line into the dark — the way you leave a lamp in the window for someone who is late.' },
];

// After 2-3 — the understudy, the star on the door, and a photograph with only the eyes left.
const I2_UNDERSTUDY: Shot[] = [
  { kind: 'narrate', bg: 'parlour', tone: 'warm', text: 'Below the stage the Gloaming kept its other face. A corridor of numbered doors, the paint worn pale at hand height. Coat hooks. A fire bucket full of cigarette ends. A notice, yellowed to the colour of old teeth: NO WHISTLING IN THE WINGS — BY ORDER.' },
  { kind: 'narrate', text: 'The mirrors had cleared. In every dressing room, inside every ring of dead bulbs, the glass now showed only what was in front of it: a chair, a powder tin, a tired face. After a year of showing something else, it seemed almost shy about it.' },
  { kind: 'narrate', text: 'In Dressing Room Two a woman sat before the glass in a white gown sewn with glass beads. The swan’s gown — a second one, cut a little smaller and a little cheaper. Her face was made up for the stage. It had been made up for a year.' },
  { kind: 'line', who: 'Clara Moss', text: 'Is it time? Somebody tell me if it’s time. They never tell the understudy anything until it is.' },
  { kind: 'line', who: 'marigold', text: 'Miss Moss. Clara. It is Valerian Rosenthal.' },
  { kind: 'line', who: 'Clara Moss', text: 'Count. You sent me roses once. Eleven years ago, after the matinée when she had the fever and I went on for the second act. I cried so hard I had to do my face again.' },
  { kind: 'line', who: 'marigold', text: 'I have never been entirely sure it was a kindness.' },
  { kind: 'line', who: 'Clara Moss', text: 'It was. Nobody sends an understudy roses. Nobody is supposed to remember she went on at all.' },
  { kind: 'line', who: 'bastian', text: 'What is an understudy?' },
  { kind: 'line', who: 'Clara Moss', text: 'Someone who learns every note of a part and prays never to sing it. You know the steps, the breaths, where the light will fall. You sit in a room under the stage, dressed and ready, for a night that is never supposed to come.' },
  { kind: 'line', who: 'Clara Moss', text: 'This year, I was the best-prepared woman in Vellmoor.' },
  { kind: 'narrate', text: 'She laughed a little at that. Then she reached up to the mirror frame, where a card had been tucked among the old telegrams, and took it down, and held it out to them without looking at it. She knew it by heart.' },
  { kind: 'letter', text: 'Clara — I am stopping. You knew before I did; you always do, it is your job. From the second of January the Swan is yours. Don’t sing it like me. Sing it like a woman who has waited eleven years and has a great deal to say. And for heaven’s sake, eat something before you go on.', sign: '— G.' },
  { kind: 'line', who: 'Clara Moss', text: 'She was going to give me the Swan. And then the night never ended, and the second of January never came.' },
  { kind: 'line', who: 'Clara Moss', text: 'I’m not angry. I want you to understand that. I sat here a year waiting to be angry, and that never came either. You cannot be angry with a night.' },
  { kind: 'line', who: 'odile', text: 'You can be sad with one.' },
  { kind: 'line', who: 'Clara Moss', text: 'Yes. That, you can.' },
  { kind: 'line', who: 'wren', text: 'Miss Moss — when the night does end, the house will need a Swan.' },
  { kind: 'line', who: 'Clara Moss', text: 'Then I’d better keep my face on. Go on. Her room is at the end. The star on the door. Nobody ever went in there without knocking — not the manager, not even the fire inspector.' },
  { kind: 'narrate', text: 'The door at the end of the corridor had a brass star screwed into it at eye level, polished by years of thumbs. Beneath it someone had chalked, long ago, in a stagehand’s capitals: MISS AMBRE — AND THAT MEANS YOU.' },
  { kind: 'narrate', text: 'Valerian stopped a pace short of it. His hand rose toward the handle and stayed in the air a little way from the brass, as though there were a pane of glass between them, and always had been.' },
  { kind: 'line', who: 'marigold', text: 'She said after the curtain. The curtain has not come down.' },
  { kind: 'line', who: 'wren', text: 'Count—' },
  { kind: 'line', who: 'marigold', text: 'I have waited forty years to be asked into that room, Keeper. I find I can wait a little longer. Go in. Tell me nothing unless you must. She was very particular about cues.' },
  { kind: 'narrate', text: 'Inside, it smelled of greasepaint and violets and the cold coal of a fire that had gone out a year ago. A chaise longue with a shawl flung over its arm. A kettle on a spirit stove. A wall so thick with telegrams and postcards and pinned-up programmes that no wall showed.' },
  { kind: 'narrate', text: 'Every one of them was blank. Every card, every telegram, every message of good luck from thirty-eight years of first nights — wiped to the colour of milk. The Dimming had gone through this room like a maid with a damp cloth.' },
  { kind: 'line', who: 'bastian', text: 'All those people wishing her well. And none of their words left.' },
  { kind: 'line', who: 'wren', text: 'The words are not gone. Only the ink. Someone remembers sending every one of these. That has to count for something.' },
  { kind: 'narrate', text: 'On the dressing table, propped against the mirror, was an envelope. Unlike everything else in the room it had kept its ink — perhaps because the man it was meant for had never once stopped saying her name. It read: Valerian. After the curtain.' },
  { kind: 'narrate', text: 'Corvin did not open it. He put it in his satchel with the others, between a love letter from Corvid Lane and an unsigned plea from a street that no longer had a name — and somewhere in the house the note seemed, for a moment, very slightly warmer.' },
  { kind: 'narrate', text: 'Beside the envelope stood a photograph in a silver frame. This very room. Gloria in the swan’s gown, kneeling, laughing. Beside her a small girl in a blanket, in a wicker bath-chair. Behind the girl a man in a waistcoat, his hands resting on the back of the chair.' },
  { kind: 'narrate', text: 'The faces had gone, softened to pale thumbprints, the way the Dimming softens everything that might be loved. All but one thing. The man’s eyes were still there — grey, tired, fixed on the child with a terrible, careful attention, as if she were a flame in a draught.' },
  { kind: 'line', who: 'bastian', text: '…' },
  { kind: 'line', who: 'odile', text: 'Columbine?' },
  { kind: 'line', who: 'bastian', text: 'My joints hurt. All of them at once. Like when the waltz plays.' },
  { kind: 'narrate', text: 'On the back of the frame, in Gloria’s hand: For my best audience, Box Seven, who always clapped for the chorus. With love from the Swan. Christmas Eve, 1929. Below it a second line had been written, and then scrubbed away by something that was not a hand.' },
  { kind: 'line', who: 'odile', text: 'His eyes are the same colour as yours.' },
  { kind: 'line', who: 'bastian', text: 'Lots of people have grey eyes. Half of Corvid Lane has grey eyes. It is a very common colour. It is the colour of the sky here.' },
  { kind: 'line', who: 'odile', text: 'Yes. Of course it is.' },
  { kind: 'narrate', text: 'Columbine turned from the photograph and found herself facing the long mirror instead. For one heartbeat the glass did not show the dressing room at all.' },
  { kind: 'narrate', text: 'It showed a small blue bedroom, and a marionette in red dancing at the foot of a narrow bed — one, two, three, one, two, three — and from the pillows, very faintly, someone too tired to lift their hands was trying to clap.' },
  { kind: 'narrate', text: 'Then the mirror was a mirror again, and Columbine was a girl made of porcelain, standing very still in a dead woman’s dressing room with her cut strings trembling.' },
  { kind: 'line', who: 'wren', text: 'What did you see?' },
  { kind: 'line', who: 'bastian', text: 'Someone I was supposed to be dancing for. I don’t know who. I think — I think I was very good at it.' },
  { kind: 'line', who: 'wren', text: 'Then you can tell them so, when we find them.' },
  { kind: 'narrate', text: 'In the corridor Valerian was waiting exactly where they had left him, a pace from the door, holding a single rose by the stem. He asked them nothing. Corvin gave him the envelope. He looked at his own name in her hand a long time, and put it away unopened, beside the card.' },
  { kind: 'line', who: 'marigold', text: 'After the curtain.' },
  { kind: 'line', who: 'wren', text: 'After the curtain.' },
];

// After 2-4 — the Maestro, the music box he copied the waltz for, and a dance on an empty stage.
const I3_WALTZ: Shot[] = [
  { kind: 'narrate', text: 'When the last Lamp-Eater had been cracked out of the timpani, the orchestra pit fell quiet — or as quiet as anything could be beneath the note. Music stands lay toppled like a small felled wood. Sheet music drifted ankle-deep, every page blank as fresh snow.' },
  { kind: 'narrate', text: 'In the middle of it, on the conductor’s podium, a stout man in a tailcoat gone green at the seams was still beating time with half a baton. Three in a bar. Patient. Furious. He had not missed a beat in a year.' },
  { kind: 'line', who: 'Maestro Benedetti', text: 'And — one, two, three — and — no, no, no, the horns are dragging again. They drag in their sleep. I have told them. I have told them in four languages and one gesture.' },
  { kind: 'line', who: 'marigold', text: 'Maestro. Ilario. You may put the baton down. The horns have gone home.' },
  { kind: 'line', who: 'Maestro Benedetti', text: 'Home? Without being dismissed? I shall have them— ah. Rosenthal. You. Of course you. Who else would still be in the house at this hour, telling me how to run my pit.' },
  { kind: 'narrate', text: 'He lowered the baton at last, and looked at his own hand as though it belonged to someone else. It had been moving so long it no longer quite knew how to stop.' },
  { kind: 'line', who: 'Maestro Benedetti', text: 'I could not end it. You understand? Every time I brought the waltz home to the final chord, it went round again. One, two, three. As if the music itself had forgotten there was an ending written down.' },
  { kind: 'line', who: 'odile', text: 'It is the same waltz that lives in Columbine. She has carried it out of a toyshop window and all the way here, like a coal in a closed hand.' },
  { kind: 'line', who: 'Maestro Benedetti', text: 'The marionette? Let me look at you, signorina. Hm. Turn. Again. You stand like a dancer who was taught by a metronome and a very loving parent.' },
  { kind: 'line', who: 'bastian', text: 'Do you know what the waltz is called?' },
  { kind: 'line', who: 'Maestro Benedetti', text: 'Do I know? It is the Midnight Waltz, from the second act of The Glass Swan. The Swan dances on the frozen lake with her lamplighter while the town sleeps. Eight minutes of the finest music ever written for a theatre that could not afford it.' },
  { kind: 'line', who: 'marigold', text: 'I afforded it.' },
  { kind: 'line', who: 'Maestro Benedetti', text: 'He afforded it, he says, as if money were the hard part. Money is never the hard part. The hard part is a soprano who can dance in three-four and still have the breath to break your heart at the end of it.' },
  { kind: 'line', who: 'wren', text: 'Maestro — did anyone else ever ask you for that waltz? Outside the theatre?' },
  { kind: 'narrate', text: 'Benedetti was quiet for a time. He took off his spectacles and polished them on his sleeve, which only made them worse.' },
  { kind: 'line', who: 'Maestro Benedetti', text: 'Once. This last December. A man came to the stage door after rehearsal — a craftsman, by his hands. Watch oil under the nails. Quiet. Very polite, in the way of men who have stopped expecting the world to be polite back.' },
  { kind: 'line', who: 'Maestro Benedetti', text: 'He wanted the waltz written out small, the melody only, for a music box. His daughter could no longer come to the theatre, he said. She had loved it so. He wished her to have it by her bed. I copied it myself, that night, by hand.' },
  { kind: 'line', who: 'Maestro Benedetti', text: 'He paid me with this. I told him it was too much. He said it was the only thing he had made that year that was not for her.' },
  { kind: 'narrate', text: 'From his waistcoat he drew a pocket watch — silver, plain, made by someone with no need to show off. The case bore no maker’s name, only a tiny engraved swan. Its hands stood at twelve. Both of them. Exactly, like a pair of hands pressed together.' },
  { kind: 'line', who: 'Maestro Benedetti', text: 'It kept perfect time. Perfect. Until midnight. Then it simply… held. Like everything else.' },
  { kind: 'line', who: 'bastian', text: 'A music box by a bed.' },
  { kind: 'line', who: 'bastian', text: 'I think I know that bed.' },
  { kind: 'narrate', text: 'Nobody said the obvious thing. Seraphine looked at Corvin, and Corvin looked at the watch, and Valerian looked at the stage — where the empty spotlight lay waiting, as it had all year, for somebody to step into it.' },
  { kind: 'line', who: 'Maestro Benedetti', text: 'Well. I am not a man who leaves a waltz unfinished. Strings! Whoever is left. From the top of the second act. Let us try it once more with somebody actually dancing, and see whether it consents to end.' },
  { kind: 'narrate', text: 'There were not many left: a cellist who had woken in the pit with her bow still in her hand, an old second violin, a boy with a flute who had been fourteen at the start of the year and was fifteen now without having noticed. It was enough.' },
  { kind: 'line', who: 'marigold', text: 'Columbine.' },
  { kind: 'line', who: 'bastian', text: 'Count?' },
  { kind: 'line', who: 'marigold', text: 'In forty years I have danced in this house exactly never. I watched from the box. I always meant to ask someone, and I always found a reason not to. I wonder if you would do me the honour.' },
  { kind: 'line', who: 'bastian', text: 'My legs were never my own. Somebody made them to dance for somebody else.' },
  { kind: 'line', who: 'marigold', text: 'Then tonight, my dear, you shall lend them to me, and I shall give them back. That is the whole difference between a dance and a debt.' },
  { kind: 'narrate', text: 'He took her porcelain hand in his gloved one, and they climbed the little stair from the pit onto the stage, into the spotlight that had waited a year for someone. The cello began. The violin found it. The flute came in a bar late, and very sorry.' },
  { kind: 'narrate', text: 'Columbine knew every step. Not the way you know a road — the way you know your own name. One, two, three. Her cut strings swung out around her as she turned, catching the light like the ends of a red ribbon.' },
  { kind: 'narrate', text: 'Valerian danced badly, and with enormous dignity, and never once looked at his feet. He looked at the empty boxes, and the full stalls, and the place on the stage where Gloria would have stood, and then at the marionette in his arms. And he smiled.' },
  { kind: 'narrate', text: 'In the stalls, heads began to turn. Not many. A woman in a fur stole. A boy in a sailor collar. The old man with the hearing trumpet, who lowered it from his ear and, very slowly, began to beat time on his knee.' },
  { kind: 'line', who: 'odile', text: 'They are watching. Corvin, they are actually watching.' },
  { kind: 'line', who: 'wren', text: 'Of course they are. It is a theatre. It is the one thing they have not forgotten how to do.' },
  { kind: 'narrate', text: 'At the edge of the pit Seraphine and Corvin stood side by side and watched them dance. For a while neither spoke. Above them the note went on, and the waltz went round beneath it, and for once the two of them seemed almost to be in the same key.' },
  { kind: 'line', who: 'odile', text: 'I should tell you something, before we reach her.' },
  { kind: 'line', who: 'wren', text: 'The future you won’t speak of?' },
  { kind: 'line', who: 'odile', text: 'Not that one. A smaller one. When the note ends, she ends with it. A year is a long time to hold a breath. There is nothing left of her now but the holding.' },
  { kind: 'line', who: 'wren', text: 'You are certain.' },
  { kind: 'line', who: 'odile', text: 'I am never certain. I am only frequently right. The morning comes, Corvin. Not for everyone.' },
  { kind: 'line', who: 'wren', text: 'Does he know?' },
  { kind: 'line', who: 'odile', text: 'Look at him. He has known for a year. He is dancing anyway.' },
  { kind: 'narrate', text: 'Corvin’s hand went, without his meaning it to, to his inside pocket, where the one letter he had never opened lay against his ribs. To whoever stops the clock. On its back, in a child’s pencil, underlined three times: PROJECT FIREFLY.' },
  { kind: 'narrate', text: 'Somebody small had made a plan, with a name and rules and a secret. He did not take the envelope out. He had never yet been sure that he was the one it was meant for — only that it had been waiting, like the spotlight, for someone to step into it.' },
  { kind: 'narrate', text: 'The waltz came round to its final bar. Benedetti held his half-baton high, and the little orchestra held its breath — and for the first time in a year the music did what was written. It resolved. It ended.' },
  { kind: 'narrate', text: 'Valerian bowed to the marionette. The marionette, after a moment’s thought, curtsied — perfectly, the way she had been made to. And somewhere in the stalls two thousand people who had forgotten how began, raggedly, to applaud.' },
  { kind: 'line', who: 'Maestro Benedetti', text: 'There. You see? It ends. Everything ends, if you play it properly. That is the only mercy music has ever had to offer.' },
  { kind: 'line', who: 'bastian', text: 'Count. Thank you for giving them back.' },
  { kind: 'line', who: 'marigold', text: 'Your legs? My dear, I never had them. You only let me borrow the dance. I shall be paying it back, with interest, for the rest of my life.' },
];

// After 2-5 — the programme girl in the rigging, her paper snow, and a door with an hourglass on it.
const I4_RIGGING: Shot[] = [
  { kind: 'narrate', tone: 'cold', text: 'Forty feet above the stage the fly gallery is a narrow iron walk bolted to the brick, rigged with more rope than a ship. From here the stagehands once flew in the moon, the bridge, the snow. From here the whole stage looks like a lit page, very far down.' },
  { kind: 'narrate', text: 'The freed fireflies did not rise. They fell — slowly, like seeds — down through the dark of the flies, past the painted moon and the canvas sky, into the stalls. Each one drifted until it found someone, and settled on them, and went out.' },
  { kind: 'narrate', text: 'Where one settled, a person sat up. A man in Row C touched his own face as if surprised to find it there. Two sisters in the dress circle turned to each other at the same moment and said each other’s names, and laughed, and then could not stop crying.' },
  { kind: 'line', who: 'odile', text: 'Every one is a name coming home. I have read the stars half my life and never seen anything so precise. Not one of them lost its way.' },
  { kind: 'line', who: 'A Small Voice', text: 'The blue one. Did the blue one get down? Please say the blue one got down.' },
  { kind: 'narrate', text: 'She was wedged into the angle where the gallery met the wall, behind a pinrail of tied-off ropes: a girl of twelve or so in an usherette’s pillbox hat two sizes too big, a programme tray still hung round her neck on its strap. The tray was full of chocolate wrappers.' },
  { kind: 'line', who: 'bastian', text: 'It got down. It went to a lady in Row F. She sat up and said a name. I think it was yours.' },
  { kind: 'line', who: 'A Small Voice', text: 'Was it Nettie? Did she say Nettie?' },
  { kind: 'line', who: 'bastian', text: 'Yes. I think so. Yes.' },
  { kind: 'line', who: 'Nettie Clare', text: 'That’s me. That’s my mum. She saved a year for that seat. She wanted to see me work, just once — I sell the programmes in the interval, and tonight I was doing the snow.' },
  { kind: 'line', who: 'wren', text: 'The snow?' },
  { kind: 'line', who: 'Nettie Clare', text: 'For the last scene. There’s a big canvas cradle up there full of paper snow, and when the bells start you pull the rope, slow and steady, so it comes down soft over the bridge. Mr. Hodge used to do it. He let me, for the gala. It was a treat.' },
  { kind: 'line', who: 'Nettie Clare', text: 'Then everything went dark and the beetles came, and I hid. And then I stayed hid. I didn’t know how long. I ate the interval chocolates. All of them. I’m sorry, Count.' },
  { kind: 'line', who: 'marigold', text: 'My dear girl, I bought those chocolates in the confident expectation that someone would eat them. You have fulfilled a contract. I may give you a rise.' },
  { kind: 'narrate', text: 'Valerian lowered himself, with some care for his knees, onto the iron walk beside her. Close to, he could see her hands. The fingertips were grey with pencil, and the nails were bitten to the quick.' },
  { kind: 'line', who: 'marigold', text: 'What have you been doing up here, all this time?' },
  { kind: 'line', who: 'Nettie Clare', text: 'Writing to Mum. Every day. On the backs of the programmes. I couldn’t post them, so I tore them up small and put them in the snow cradle. I thought, when the scene comes round again, she’ll be sitting right underneath.' },
  { kind: 'narrate', text: 'Corvin looked up. The canvas cradle hung above them on its lines, swollen and heavy. Through a split in the seam he could see the paper inside: thousands of small torn squares, each with a word or two in a child’s pencil. Dear. Today. Miss you. Still here.' },
  { kind: 'line', who: 'wren', text: 'A year of letters.' },
  { kind: 'line', who: 'Nettie Clare', text: 'Is that stupid?' },
  { kind: 'line', who: 'wren', text: 'No. It is the least stupid thing I have heard since the clock stopped. I carry the post, Nettie. I would have been proud to deliver every one of them.' },
  { kind: 'line', who: 'Nettie Clare', text: 'You can. In the last scene. If there’s ever a last scene.' },
  { kind: 'line', who: 'marigold', text: 'There will be. I have paid for it.' },
  { kind: 'bg', bg: 'theatre', tone: 'cold' },
  { kind: 'narrate', text: 'Further along the gallery, where the iron walk turned a corner and climbed a short ladder toward the roof, the ropes began to hiss. Not with tension. With sand.' },
  { kind: 'narrate', text: 'It ran in a thin bright stream from under a narrow door set into the brick — a door no stagehand had reason to use, painted bottle-green, with a small gilt hourglass where the number should have been. The sand pooled on the walk. It did not seem to be running out.' },
  { kind: 'line', who: 'odile', text: 'Whose door is this?' },
  { kind: 'line', who: 'Nettie Clare', text: 'The Countess’s. She has rooms up top, over the whole roof. You’re not supposed to go up. Mr. Hodge said she pays the theatre rent and the theatre pays her no attention, and that’s how both of them like it.' },
  { kind: 'line', who: 'marigold', text: 'Ophelia Sablier. A countess of no fixed estate and very fixed opinions. She once told me, over a perfectly good supper, that she collected seconds. I assumed it was a joke. Most of what she says sounds like a joke, until it isn’t.' },
  { kind: 'line', who: 'Nettie Clare', text: 'She wasn’t in her box. That night. She always has Box One, every gala, every first night. I sell her a programme and she tips me in foreign coins. That night the box was empty. First time ever.' },
  { kind: 'narrate', text: 'Pinned to the green door by a hatpin was a visiting card, its edges gone brittle. On it, in a fast, slanting, entirely unapologetic hand:' },
  { kind: 'letter', text: 'Out. Playing chess with a friend who cannot sleep. Back in a minute.', sign: '— O.S.' },
  { kind: 'line', who: 'wren', text: '“Back in a minute.”' },
  { kind: 'line', who: 'odile', text: 'A minute is a very long time, in this city.' },
  { kind: 'narrate', text: 'Corvin knocked. The sound went into the door and did not come back, the way a stone goes into deep water. Behind the wood, very faint, something ticked — not a clock. Something finer. The whisper of grains through a narrow glass, one by one, unhurried.' },
  { kind: 'line', who: 'bastian', text: 'There is no one in there. But something is counting.' },
  { kind: 'line', who: 'marigold', text: 'Then let it count. We have a prima donna to see to, and I have never in my life kept one waiting on purpose.' },
  { kind: 'narrate', text: 'Seraphine lingered. Through a skylight above the door the frozen sky showed — the same stars in the same places, the same midnight hung over the city like a cloth over a birdcage. She looked at it a long time.' },
  { kind: 'line', who: 'odile', text: 'Every star is where it was. Every one. And yet the sand is falling.' },
  { kind: 'line', who: 'wren', text: 'What does that mean?' },
  { kind: 'line', who: 'odile', text: 'That someone in this city is still keeping time. And has not told the rest of us.' },
  { kind: 'narrate', text: 'They went back down the ladder. Behind them, at the corner of the gallery, Nettie Clare sat with her empty tray across her knees and her hand on the snow cradle’s rope, as if it were a bell-pull, and waited for her cue. Below her, the note went on.' },
];

// After 2-7 — the Count’s box, the question he asked in 1903, and the call for the last act.
const I5_ROSES: Shot[] = [
  { kind: 'narrate', text: 'The Rosenthal box is the third on the grand tier, stage left — near enough to see the singers sweat, far enough that they cannot see you weep. It has eight chairs. For forty years, seven of them had been empty.' },
  { kind: 'narrate', text: 'The Count had brought them there to rest before the last act, as a host brings guests into the drawing room before dinner. He found a decanter, and glasses, and a tin of shortbread no older than the Dimming, and served them with the air of a man pouring for royalty.' },
  { kind: 'line', who: 'marigold', text: 'Sit, please. A patron never lets a guest stand. It is the only rule my father and I ever agreed upon.' },
  { kind: 'line', who: 'bastian', text: 'This is where you watched her from. Every night.' },
  { kind: 'line', who: 'marigold', text: 'Every opening night, every closing night, and a good many in between. Two thousand three hundred and six performances. I kept count. I told you — I always count.' },
  { kind: 'narrate', text: 'On the rail of the box, worn into the gilt where one hand had rested for forty years, was a pale smooth patch the exact shape of a palm. Valerian set his own hand on it now without seeming to notice — a key returning to the only lock it fits.' },
  { kind: 'line', who: 'wren', text: 'May I ask you something, Count?' },
  { kind: 'line', who: 'marigold', text: 'You are going to ask why I never married her. Everyone asks eventually. The waiters at the Meridian used to run a book on it.' },
  { kind: 'line', who: 'wren', text: 'I was going to ask whether you ever asked.' },
  { kind: 'line', who: 'marigold', text: '…That is a better question. Yes. Once.' },
  { kind: 'narrate', text: 'He told it plainly, as he had told nothing else that night. No flourish. As though he had rehearsed it so often, alone, that every ornament had worn off it, the way the gilt had worn from the rail.' },
  { kind: 'line', who: 'marigold', text: 'Nineteen hundred and three. The hundredth Swan. I took her to supper at the Hôtel Meridian and asked her between the fish and the game, because I am a coward and wanted the waiter to have a reason to interrupt.' },
  { kind: 'line', who: 'marigold', text: 'She put down her fork. She said: “Ask me again when I stop singing. I will not make you share me with two thousand people a night. You would hate it, and you would be far too polite to say so.”' },
  { kind: 'line', who: 'odile', text: 'And you waited.' },
  { kind: 'line', who: 'marigold', text: 'Twenty-six years. I did not ask again. One does not hurry a woman like that toward the end of the thing she was born to do. I sent the roses, and she sent one back, and I told myself that was a kind of conversation.' },
  { kind: 'line', who: 'marigold', text: 'Then, last autumn, she told the papers she was retiring. The gala would be her last Swan. And I thought — Valerian, you old fool, you have perhaps four months to learn how to propose without a fish course.' },
  { kind: 'line', who: 'bastian', text: 'Did you learn?' },
  { kind: 'line', who: 'marigold', text: 'I wrote it out forty times. I had a ring made — not too large; she hated anything that caught the light better than she did. It is in my waistcoat. It has been in my waistcoat a year. It has become, I think, a sort of second heart. It keeps worse time than the first.' },
  { kind: 'narrate', text: 'Below them the stalls had half emptied. Freed people moved up the aisles in ones and twos, holding one another’s elbows, stopping to stare at the chandelier as if they had never seen a ceiling before. Others still sat, waiting. The note went on.' },
  { kind: 'line', who: 'wren', text: 'You have her letter. The one from the dressing room. You could open it now.' },
  { kind: 'line', who: 'marigold', text: 'I could. And then I would know what she meant to tell me, and I would go down there knowing it, and I should not be able to help hoping. No, Keeper. She asked me not to leave before the curtain. I shall do as I am told. For once.' },
  { kind: 'line', who: 'marigold', text: 'Seraphine. You have been looking at me all evening as though I were a star you had already read. Be honest with an old man. When the note ends — will she?' },
  { kind: 'narrate', text: 'Seraphine did not lie. It was one of the things about her that people found hardest to forgive, and one of the things they came back for.' },
  { kind: 'line', who: 'odile', text: 'A note does not own the silence after it, Count. The silence owns the note. I cannot promise you she stays. I can promise you she will know who she was, when she goes.' },
  { kind: 'line', who: 'marigold', text: 'Then that is the encore. That will do. That will more than do.' },
  { kind: 'narrate', text: 'He looked out over the rail at the empty stage. Nobody hurried him. When he spoke again it was lightly — the way men speak when the thing beneath the words is too heavy to lift any other way.' },
  { kind: 'line', who: 'marigold', text: 'I kept accounts of her, you know. My father’s habit. Every rose an entry. Every curtain call a column. Forty years of it, and the book has never once balanced.' },
  { kind: 'line', who: 'marigold', text: 'The more I paid, the more I found I owed. I used to think it was a fault in the arithmetic. I have come round to thinking it is the point.' },
  { kind: 'line', who: 'marigold', text: 'I have never missed the end of a performance in forty years. I am not about to start with hers.' },
  { kind: 'line', who: 'bastian', text: 'Count… may I ask you a question too?' },
  { kind: 'line', who: 'marigold', text: 'You may ask me anything, my dear. You are the only person in Vellmoor who has ever let me lead.' },
  { kind: 'line', who: 'bastian', text: 'The man in the photograph. The one with my eyes. If he made me — if he made me to dance for somebody else — do you think he loved me? Or was I just… a thing he needed?' },
  { kind: 'narrate', text: 'Valerian took her porcelain wrist, very gently, and turned it to the lamp. There, at the joint, in brass letters so fine they could only have been set with a jeweller’s tweezers, were two initials.' },
  { kind: 'line', who: 'marigold', text: 'Nobody signs their name on every joint of a thing they do not love, Columbine. Nobody takes that much care over a tool. Whoever he is, he made you the way I wrote that proposal. Forty times over, until it was right.' },
  { kind: 'line', who: 'bastian', text: 'But he cut my strings.' },
  { kind: 'line', who: 'marigold', text: 'Perhaps. Or perhaps he only let go. From the inside, I am told, those feel very much the same.' },
  { kind: 'narrate', text: 'Down in the house a sound began that none of them had heard since they came in: a knock. Three slow knocks of a stave on the boards, from somewhere behind the curtain — the old signal, in old theatres, that the play is about to begin.' },
  { kind: 'line', who: 'Abel Finch', text: 'Beginners, please! Beginners to the stage for the last act! Places, please, ladies and gentlemen — this is your call!' },
  { kind: 'line', who: 'marigold', text: 'Finch. He was callboy before he was prompter. He has not called the half in twenty years. Listen to him. He sounds about fifteen.' },
  { kind: 'narrate', text: 'And then, beneath the old man’s voice, from the wings — from everywhere — a laugh like a curtain tearing. The note rose with it, sharper, brighter, until the dark crystal of the chandelier began to sing along in sympathy.' },
  { kind: 'line', who: 'gloam', text: 'Last rehearsal is over, darlings. I do hope you took notes. Places, please. The house is full, and the house has waited long enough.' },
  { kind: 'line', who: 'wren', text: 'Is everyone ready?' },
  { kind: 'line', who: 'odile', text: 'No. Which, I think, is how one is meant to feel before a last act.' },
  { kind: 'narrate', text: 'Valerian rose. He took off his gloves, finger by finger, and laid them on the rail over the pale worn patch, as though leaving them to keep his place. From the bucket he chose a single rose — the reddest — and put it through his buttonhole.' },
  { kind: 'line', who: 'marigold', text: 'Forty years I have watched this stage from up here. I have never once set foot on it. Patrons do not. It is considered vulgar.' },
  { kind: 'line', who: 'wren', text: 'And tonight?' },
  { kind: 'line', who: 'marigold', text: 'Tonight, Keeper, I intend to be extremely vulgar. Shall we?' },
];

const END: Shot[] = [
  { kind: 'narrate', text: 'Madame Gloam came apart the way a costume does at the end of a long run: one stitch, and then all of them. Violet thread unspooled from her in the spotlight and lay on the boards in loose, shining coils, like the ribbon off a box nobody had been allowed to open.' },
  { kind: 'narrate', text: 'The fireflies sewn into her hem tore free. They did not fall this time. They rose — up past the boxes, up past the gods — and gathered in the great dark chandelier like bees coming home to the hive.' },
  { kind: 'narrate', text: 'The chandelier of the Gloaming blazed for the first time in a year. Four thousand drops of crystal caught at once, and the whole red-and-gold house leapt out of the dark, as if it had been holding its breath all this while only to be seen.' },
  { kind: 'narrate', text: 'Two thousand people remembered, all at once, that they had homes to go to. And yet not one of them stood up. Because the note had not ended.' },
  { kind: 'narrate', text: 'Where Madame Gloam had been, in the very centre of the light, stood a woman in a white gown sewn with glass beads. Grey in her hair. Arms a little raised, as a singer holds them to keep the ribs open. Eyes closed. Mouth open on the note. Singing.' },
  { kind: 'line', who: 'odile', text: 'This is what is left of her. The Dimming has let go of her — but she has not let go of the note. She does not know how to stop.' },
  { kind: 'line', who: 'wren', text: 'What happens if we wake her?' },
  { kind: 'line', who: 'odile', text: 'She is not asleep, Corvin. She is waiting. A held note ends when it is answered, or when the singer runs out of breath — and she ran out of breath a year ago. Only the question is keeping her here.' },
  { kind: 'line', who: 'marigold', text: 'Then somebody had better answer it.' },
  { kind: 'narrate', text: 'Columbine stepped to the very front of the stage, above the little hooded box, and — remembering — knocked her porcelain heel on the boards. Twice. Like a friend at the door.' },
  { kind: 'line', who: 'Abel Finch', text: 'Bar two hundred and twelve! The lamplighter’s answer — one word, on the downbeat, under her note. Maestro, if you would be so kind.' },
  { kind: 'line', who: 'Maestro Benedetti', text: 'Strings! Whoever is left! Bar two hundred and twelve, pianissimo — and if anybody drags, I shall personally see them buried in the brass section.' },
  { kind: 'narrate', text: 'The little orchestra found the last page of The Glass Swan. Under Gloria’s note the strings came in, soft as breath on a window, and the music did what it had been written to do: it made a space. A space exactly the shape of one word.' },
  { kind: 'line', who: 'wren', text: 'Where is the tenor?' },
  { kind: 'line', who: 'Abel Finch', text: 'Gone. Ran out of the stage door at the thirteenth stroke and into the fog, and nobody’s seen him since. There is no lamplighter, son. There is only the place where he ought to be.' },
  { kind: 'narrate', text: 'Everyone on the stage turned, slowly, and looked at the Count.' },
  { kind: 'line', who: 'marigold', text: 'Absolutely not. I cannot sing. She told me so herself, in 1889, with a mouthful of pins. It was the very first thing she ever said to me.' },
  { kind: 'line', who: 'wren', text: 'She did not ask you to sing. She asked you not to leave before the curtain.' },
  { kind: 'narrate', text: 'Valerian was silent. Then he took the rose from his buttonhole, and laid it on the lip of the prompter’s box, the way a man lays down a coin he has carried for luck and no longer needs.' },
  { kind: 'line', who: 'marigold', text: 'I cannot sing. I never could. But I can say a word I’ve kept for forty years, and keep it one breath more, and then let go.' },
  { kind: 'narrate', text: 'He went first into the wings — there is a proper way to come on, and he had watched it done two thousand times — and then Valerian Rosenthal entered, as a player, upon the stage of the Royal Gloaming Theatre. It was eleven paces from the wings to the bridge.' },
  { kind: 'narrate', text: 'He took them as though each one cost something — and as though he had always known the price, and had been saving for it all his life.' },
  { kind: 'narrate', text: 'High above, in the fly gallery, a twelve-year-old girl heard her cue and pulled the rope — slow and steady, the way Mr. Hodge had taught her. The canvas cradle tipped.' },
  { kind: 'narrate', text: 'Snow came down over the lamplighter’s bridge. Not paper snow. Letters — a year of them, torn small, each with a word or two in a child’s pencil. Dear. Today. Miss you. Still here. It fell on the stage, and the pit, and the front stalls, where a woman in Row F held out her hands to catch it.' },
  { kind: 'narrate', text: 'Corvin did not know the blocking. But he knew that in the last act the lamplighter carries a lamp. He lifted the Lantern and stood at the end of the bridge, and its light went out across the boards and found her.' },
  { kind: 'narrate', text: 'Valerian stood beside her in the falling snow. He did not touch her. The music held its breath. Benedetti’s half-baton hung in the air above the pit, waiting for the downbeat — and came down.' },
  { kind: 'line', who: 'marigold', text: 'Gloria.' },
  { kind: 'narrate', text: 'It was flat. It was very, very flat — the voice of a gate that wanted oiling, of a man who had never sung a note in public and had chosen to begin in front of two thousand people. It was the most beautiful thing any of them had ever heard.' },
  { kind: 'narrate', text: 'And Gloria’s voice came down from the high note the way the composer had written it — one long step to the end of the phrase — and the word she had held open for a year closed at last around itself. Name.' },
  { kind: 'narrate', text: 'And the note did not go on.' },
  { kind: 'narrate', text: 'For the first time in a year there was silence in the Royal Gloaming Theatre: the silence a theatre is built for, two thousand people not breathing at once. It lasted perhaps three seconds.' },
  { kind: 'narrate', text: 'Then, from the back of the stalls, an old man lowered his hearing trumpet and called out, in a cracked voice, the name he had just remembered.' },
  { kind: 'line', who: 'The Audience', text: 'Gloria!' },
  { kind: 'narrate', text: 'And then the whole house. Two thousand people on their feet, in furs and pearls and their one good coats, shouting a name they had not been able to say for a year — Gloria! Gloria Ambre! — until the chandelier rang with it and the snow on the stage danced.' },
  { kind: 'narrate', text: 'She opened her eyes.' },
  { kind: 'line', who: 'Gloria Ambre', text: 'Valerian. You’re flat.' },
  { kind: 'line', who: 'marigold', text: 'So I have been told. By an authority.' },
  { kind: 'line', who: 'Gloria Ambre', text: 'You came on. You actually came on. Forty years, and you never once set foot on my stage.' },
  { kind: 'line', who: 'marigold', text: 'You told me not to leave before the curtain. You said nothing whatever about coming up.' },
  { kind: 'line', who: 'Gloria Ambre', text: 'No. I didn’t, did I. How careless of me. And you brought nothing, as you were told. Not a single rose. I hardly know you.' },
  { kind: 'line', who: 'marigold', text: 'I brought the only thing in this house I never paid for.' },
  { kind: 'narrate', text: 'She was lighter than she had been. Not thinner — lighter, the way a window grows light before morning. Through the white of her sleeve, if you looked closely, you could see the snow still falling on the other side.' },
  { kind: 'line', who: 'Gloria Ambre', text: 'It has been a long time, hasn’t it? I can feel it in my ribs. All that time on one note. I could hear someone saying a name, every night, from very far away. I didn’t know it was mine. I only knew I wanted to hear it again.' },
  { kind: 'line', who: 'marigold', text: 'That was me, I am afraid. Every night, like winding a clock in an empty house. It was the best I could manage.' },
  { kind: 'line', who: 'Gloria Ambre', text: 'It was enough. It was always enough. That was the whole trouble with you, Valerian — you never once believed it.' },
  { kind: 'line', who: 'marigold', text: 'I have your letter. From the dressing room. I have not opened it. You said after the curtain.' },
  { kind: 'line', who: 'Gloria Ambre', text: 'Good. Then I get to say it first, without a prompter, the way I meant to. Abie — don’t you dare give me the line.' },
  { kind: 'narrate', text: 'In the little hooded box at her feet, an old man put both inky hands over his mouth, and kept the silence for her, as he had been asked.' },
  { kind: 'line', who: 'Gloria Ambre', text: 'Ask me again.' },
  { kind: 'narrate', text: 'For a moment the Count of Rosenthal, who had kept a witticism ready for every occasion since 1889, had nothing to say at all. His hand went to his waistcoat. It came out holding something small that caught the light — not too much. Never better than she did.' },
  { kind: 'line', who: 'marigold', text: 'Gloria Ambre. Glory. Would you— will you have supper with me?' },
  { kind: 'line', who: 'Gloria Ambre', text: 'Yes. Order for me. You always knew exactly what I wanted, and you always, always asked anyway.' },
  { kind: 'narrate', text: 'She held out her hand. He put the ring on it. It fitted. Of course it fitted; he had had forty years to guess.' },
  { kind: 'line', who: 'Gloria Ambre', text: 'And you. The little dancer. Come here, where the light is.' },
  { kind: 'narrate', text: 'Columbine came. Gloria put a hand — very light now — beneath the marionette’s chin and turned her face toward the Lantern, the way a dresser turns an actress to the mirror to check her paint.' },
  { kind: 'line', who: 'Gloria Ambre', text: 'I told you once already, didn’t I, when I was the other thing. I meant it then, too. You have his eyes. He made you with such care.' },
  { kind: 'line', who: 'bastian', text: 'Who? Please. Whose eyes?' },
  { kind: 'line', who: 'Gloria Ambre', text: 'He brought his girl to Box Seven every Saturday, until she couldn’t come any more. She clapped for the chorus. Nobody claps for the chorus. So at Christmas I went to sing for her instead, by her bed.' },
  { kind: 'line', who: 'Gloria Ambre', text: 'And at the foot of the bed there was a dancer in red, sitting very straight, waiting for the music. I thought it was the loveliest thing I had ever seen a man make with his hands.' },
  { kind: 'line', who: 'Gloria Ambre', text: 'Go up, little one. He is waiting for you at the top of the world, and he has waited a very long time. And tell her — tell her the Swan said she was the best audience she ever had.' },
  { kind: 'line', who: 'bastian', text: 'Tell who?' },
  { kind: 'narrate', text: 'But Gloria Ambre had already turned, as singers turn, toward the house.' },
  { kind: 'narrate', text: 'She walked downstage to the very edge of the boards, above Finch’s little box, into the full blaze of the chandelier. Two thousand people were still on their feet. She looked at them — all of them, it seemed, one at a time.' },
  { kind: 'narrate', text: 'Then she bowed: the deep, slow, old-fashioned bow of a woman who had first learned it at sixteen, terrified, in a borrowed gown with the pins still in, and had spent thirty-eight years making it look easy. The roar that answered shook a year of dust down from the gods.' },
  { kind: 'line', who: 'Gloria Ambre', text: 'Thank you. You were a wonderful audience. You always were. Now go home, all of you. It’s terribly late, and someone is waiting up.' },
  { kind: 'line', who: 'Gloria Ambre', text: 'Bring down the curtain, darling. I should like to go off properly, for once.' },
  { kind: 'narrate', text: 'Somewhere in the wings, an old stagehand’s hand found the rope it had found ten thousand times. The great wine-red curtain of the Royal Gloaming came down, slowly and heavily, the way a long day ends.' },
  { kind: 'narrate', text: 'For a moment the stage was a small, warm room with only the five of them in it. She was smiling. Valerian was holding her hand. And then he was holding nothing, and the snow was still falling, and on the boards where she had stood lay a single swan’s feather made of glass.' },
  { kind: 'narrate', text: 'She had taken the ring with her. He found, a long while afterwards, that he was glad.' },
  { kind: 'bg', bg: 'theatre', tone: 'warm' },
  { kind: 'narrate', text: 'When the curtain rose again, the stage was empty but for an old man in a crimson coat standing in the snow with a glass feather in his hand. The house applauded him anyway. He did not appear to hear it.' },
  { kind: 'narrate', text: 'Then they went home. The Penroses, arm in arm, he still a little asleep. The old man with the hearing trumpet, who stopped at the stage door to ask whether there would be a matinée. The small girl on her father’s shoulders, both of them talking at once about the snow.' },
  { kind: 'narrate', text: 'In Row F a woman in her one good coat stood with her cupped hands full of torn paper, reading. When her daughter came down the iron stair from the flies at a dead run, programme tray bouncing round her neck, she did not look up until the last moment. Then she did not let go.' },
  { kind: 'narrate', text: 'In the wings, Clara Moss had taken off her make-up at last. She looked younger without it, and more tired, and entirely herself. Valerian found her there, and held out the glass feather.' },
  { kind: 'line', who: 'marigold', text: 'Miss Moss. I believe the Swan is yours from the second of January.' },
  { kind: 'line', who: 'Clara Moss', text: 'It isn’t the second of January, Count.' },
  { kind: 'line', who: 'marigold', text: 'It is somewhere. It must be. She was never once wrong about a date.' },
  { kind: 'narrate', text: 'Afterwards — when the house had emptied, and the chandelier burned on above two thousand empty seats, and the snow lay on the stage like the morning after a party — Valerian sat in his box, at the worn place on the rail, and opened the envelope at last.' },
  { kind: 'letter', text: 'Valerian — If you are reading this, I have sung my last Swan, and you have behaved yourself through the whole of it, which I shall believe when I see it. Twenty-six years ago at the Meridian, between the fish and the game, you asked me a question. I told you to ask again when I stopped singing.', sign: '(over)' },
  { kind: 'letter', text: 'Well. I have stopped. So here is the thing I have been rehearsing: every night for thirty-eight years, I looked for your box before I looked for my mark. I always knew where my light was. Ask me again. I have had the answer ready since 1903. It has not changed.', sign: '— Glory' },
  { kind: 'narrate', text: 'He read it twice. Then he folded it along its old creases and put it in his breast pocket with the card and the pressed petal, over the place in his waistcoat where the ring had been for a year.' },
  { kind: 'line', who: 'marigold', text: 'She went out smiling. She heard her own name sung back to her. That is all any of us want, in the end.' },
  { kind: 'line', who: 'wren', text: 'Count. I am sorry.' },
  { kind: 'line', who: 'marigold', text: 'Don’t be. I have attended two thousand three hundred and seven of her performances, Keeper. Tonight was the only one in which I was in the cast.' },
  { kind: 'line', who: 'marigold', text: 'Now. You are going somewhere, the three of you; I can see it in the way you keep looking at the door. I should like to come. I own a good deal of this city, and all of it is in the dark.' },
  { kind: 'line', who: 'wren', text: 'You would be welcome, Count. You always were.' },
  { kind: 'narrate', text: 'On their way out, Seraphine glanced up at Box One, on the grand tier, stage right. It was empty, as it had been all year. But on the red velvet of its single chair lay a small, neat drift of sand — and standing in the sand, as if set down mid-game, a single white pawn.' },
  { kind: 'line', who: 'bastian', text: 'She said I have his eyes. Whose eyes? Who made me?' },
  { kind: 'line', who: 'odile', text: 'The stars will not tell me — they are frozen at midnight. But the tide-clocks of the harbour were built by the same hand as the Cathedral Clock.' },
  { kind: 'line', who: 'wren', text: 'The same hand that made the watch in the Maestro’s pocket?' },
  { kind: 'line', who: 'odile', text: 'I would wager on it. And I never wager.' },
  { kind: 'bg', bg: 'street', tone: 'cold' },
  { kind: 'narrate', text: 'Outside, the crows were waiting on the steps of the Gloaming — all of them, lined along the portico rail in the rain, as if they had been there all along and had simply been too proud to come closer. One dropped onto Corvin’s shoulder with a letter in its beak. The envelope smelled of salt.' },
  { kind: 'letter', text: 'To the Lantern Keeper. The tide has not turned in a year. Ships lie in the mud. My son can call the sea, but the sea will not answer him. Come quickly. The lighthouse has started shining the wrong way.', sign: '— Harbourmaster Marée' },
  { kind: 'line', who: 'wren', text: 'Then we go to the docks.' },
  { kind: 'narrate', text: 'Behind them the Royal Gloaming burned bright from foyer to flies, and over the portico the brass letters caught the light from within. EVERY NIGHT A NEW NIGHT. It was not yet true. But for the first time in a year, it was no longer a lie.' },
  { kind: 'narrate', text: 'And on the bottom step of the grand staircase, where a crimson coat had sat beside a jealous lamp for a year, someone had left a single red rose. It would not wilt. But it was no longer waiting for anything.' },
];

